  SELECT 'b0381dd3-58ac-5c77-85f2-e3439b54071a', o.id, 'Skiing', 'Skiing', 'skiing', o.city, o.state, o.state_name, 'United States', '["winter"]', 'program', 'with_org', 'unverified', 'active', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now')
  FROM organizations o WHERE o.id = '830466cd-f39f-4782-a4c6-84801aa8826c' AND NOT EXISTS (SELECT 1 FROM programs WHERE organization_id = o.id AND sport_key = 'skiing');
UPDATE organizations SET sports_json = json_insert(CASE WHEN json_valid(sports_json) AND json_type(sports_json) = 'array' THEN sports_json ELSE '[]' END, '$[#]', 'skiing'), updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now')
  WHERE id = '830466cd-f39f-4782-a4c6-84801aa8826c' AND NOT EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(sports_json) AND json_type(sports_json) = 'array' THEN sports_json ELSE '[]' END) WHERE value = 'skiing');
