  SELECT '5267ee63-534b-591e-b5cb-d84b5e160f7b', o.id, 'Softball', 'Softball', 'softball', o.city, o.state, o.state_name, 'United States', '["summer"]', 'program', 'with_org', 'unverified', 'active', 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now')
  FROM organizations o WHERE o.id = 'e5fbeb2e-0a31-40ce-b467-d6ee9c85cfb4' AND NOT EXISTS (SELECT 1 FROM programs WHERE organization_id = o.id AND sport_key = 'softball');
UPDATE organizations SET sports_json = json_insert(CASE WHEN json_valid(sports_json) AND json_type(sports_json) = 'array' THEN sports_json ELSE '[]' END, '$[#]', 'softball'), updated_at = strftime('%Y-%m-%dT%H:%M:%SZ','now')
  WHERE id = 'e5fbeb2e-0a31-40ce-b467-d6ee9c85cfb4' AND NOT EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(sports_json) AND json_type(sports_json) = 'array' THEN sports_json ELSE '[]' END) WHERE value = 'softball');
